function generateRandomRoomCode(mode) {
	const num = Math.floor(100 + Math.random() * 900);
	switch (mode) {
		case "masterclass": return `MASTERCLASS-${num}`;
		case "battle": return `BATTLE-${num}`;
		case "duet": return `DUET-${num}`;
		case "pianobar": return `PIANOBAR-${num}`;
		case "relay": return `RELAY-${num}`;
		case "guess": return `QUIZ-${num}`;
		default: return `ROOM-${num}`;
	}
}
function normalizeRoomCode(rawCode, defaultMode = "masterclass") {
	if (!rawCode) return "";
	let clean = rawCode.trim().toUpperCase().replace(/^#/, "").replace(/\s+/g, "-");
	if (!clean) return "";
	if (/^\d+$/.test(clean)) switch (defaultMode) {
		case "masterclass": return `MASTERCLASS-${clean}`;
		case "battle": return `BATTLE-${clean}`;
		case "duet": return `DUET-${clean}`;
		case "pianobar": return `PIANOBAR-${clean}`;
		case "relay": return `RELAY-${clean}`;
		case "guess": return `QUIZ-${clean}`;
		default: return `MASTERCLASS-${clean}`;
	}
	if (/^M-?\d+$/.test(clean)) return clean.replace(/^M-?/, "MASTERCLASS-");
	if (/^(ROOM|AULA)-?\d+$/.test(clean)) return clean.replace(/^(ROOM|AULA)-?/, "MASTERCLASS-");
	if (/^MASTERCLASS\d+$/.test(clean)) return clean.replace(/^MASTERCLASS/, "MASTERCLASS-");
	return clean;
}
